int main(void){
    int n,m;
    scanf("%d %d",&n,&m);
    string s;
    cin>>s;
    vii pos(26,vi());
    FOR(i,0,s.length()){
        pos[s[i]-'a'].pb(i);
    }
    char x,y;
    FOR(i,0,m){
        scanf(" %c %c",&x,&y);
        if(x==y)
            continue;
        vi a = pos[x-'a'];
        vi b = pos[y-'a'];
        pos[x-'a'] = b;
        pos[y-'a'] = a;
    }
    string t(n,'a');
    FOR(i,0,26){
        FOR(j,0,pos[i].size()){
            t[pos[i][j]] = (char)('a'+i);
        }
    }
    cout<<t<<"\n";
    return 0;
